import {
  IAddHikingReceiptDTO,
  IAddHikingReceiptDTOResult,
  IHikingFinanceReceiptItemAddOrUpdateDTO,
  IHikingFinanceReceiptItemBaseDTO,
  IHikingFinanceReceiptItemDTO,
  IHikingPaymentDTO,
  IHikingReceiptCategoryDTO,
  IHikingReceiptDTO,
} from '../@types/DTO/hikingFinances.dto.types';
import {
  IHikingFinanceCurrency,
  IHikingFinanceCurrencyDTO,
  IHikingFinanceReceiptItem,
  IHikingFinanceReceiptItemBase,
  IHikingPayment,
  IHikingReceipt,
  IHikingReceiptCategory,
} from '../@types/hikingFinances.types';

export const mapBackHikingReceiptToFront = (backData: IHikingReceiptDTO): IHikingReceipt => {
  return {
    id: +backData.id,
    name: backData.name,
    date: new Date(backData.date),
    total: +backData.summ,
    totalByItems: backData.cursumm ? +backData.cursumm : 0,
    pdf_url: backData.pdf_url,
    html: backData.html,
    qr_code: backData.qr_code,
    images: {
      orig: backData.img_orig,
      600: backData.img_600,
      100: backData.img_100,
    },
    user: {
      id: +backData.id_user,
      name: backData.uname,
      surname: backData.usurname,
      photo: backData.uphoto,
    },
    author: {
      id: +backData.id_author,
    },
    participation: backData.participation
      ? backData.participation.split(',').map((s) => {
          const [id, fullName, date] = s.split('|');
          return {
            id: +id,
            fullName,
            date: new Date(date),
          };
        })
      : null,
    idCategory: backData.id_category ? +backData.id_category : null,
    totalInCurrency: backData.summ_in_currency ? parseFloat(backData.summ_in_currency) : null,
    currency:
      backData.id_currency &&
      backData.currency_name &&
      backData.currency_short_name &&
      backData.currency_symbol
        ? {
            id: +backData.id_currency,
            name: backData.currency_name,
            shortName: backData.currency_short_name,
            symbol: backData.currency_symbol,
          }
        : null,
  };
};

export const mapHikingReceiptToAddHikingReceiptDTO = (
  receipt: IHikingReceipt,
  id_hiking: number,
): IAddHikingReceiptDTO => {
  const res: IAddHikingReceiptDTO = {
    id_user: receipt.user.id,
    id_hiking,
    name: receipt.name,
    summ: receipt.total,
    img_orig: receipt.images.orig,
    img_600: receipt.images[600],
    img_100: receipt.images.orig,
    id_category: receipt.idCategory,
    id_currency: receipt.currency ? receipt.currency.id : null,
    summ_in_currency: receipt.totalInCurrency ? receipt.totalInCurrency : null,
    pdf_url: receipt.pdf_url,
    qr_code: receipt.qr_code,
    html: receipt.html,
  };

  if (receipt.id > 0) res.id = receipt.id;

  return res;
};

export const mapBackHikingReceiptAddToFront = (
  res: IAddHikingReceiptDTOResult,
  receipt: IHikingReceipt,
): IHikingReceipt => {
  return {
    ...receipt,
    id: +res.id,
  };
};

export const mapBackHikingPaymentToFront = (backData: IHikingPaymentDTO): IHikingPayment => {
  return {
    id: +backData.id,
    date: new Date(backData.date),
    total: +backData.total,
    comment: backData.comment,
    userFrom: !backData.id_user
      ? null
      : {
          id: +backData.id_user,
          name: backData.uname,
          surname: backData.usurname,
          photo: backData.uphoto,
        },
    userTo: !backData.id_target_user
      ? null
      : {
          id: +backData.id_target_user,
          name: backData.userToName,
          surname: backData.userToSurname,
          photo: backData.userToPhoto,
        },
    fundFrom: !backData.id_finance_fund
      ? null
      : {
          id: +backData.id_finance_fund,
          name: backData.fund_name ?? '',
        },
    fundTo: !backData.id_target_finance_fund
      ? null
      : {
          id: +backData.id_target_finance_fund,
          name: backData.target_fund_name ?? '',
        },
    dateCreate: new Date(backData.date),
    author: {
      id: +backData.id_author,
    },
    totalInCurrency: backData.total_in_currency ? parseFloat(backData.total_in_currency) : null,
    currency:
      backData.id_currency &&
      backData.currency_name &&
      backData.currency_short_name &&
      backData.currency_symbol
        ? {
            id: +backData.id_currency,
            name: backData.currency_name,
            shortName: backData.currency_short_name,
            symbol: backData.currency_symbol,
          }
        : null,
  };
};

export const mapBackHikingReceiptCategory = ({
  id,
  name,
  color,
  comment,
}: IHikingReceiptCategoryDTO): IHikingReceiptCategory => ({ id: +id, name, color, comment });
export const mapBackHikingFinanceCurrency = ({
  id,
  name,
  short_name,
  symbol,
}: IHikingFinanceCurrencyDTO): IHikingFinanceCurrency => ({
  id: +id,
  name,
  shortName: short_name,
  symbol,
});

export const mapFinanceReceiptItemBaseToFront = (
  backData: IHikingFinanceReceiptItemBaseDTO,
): IHikingFinanceReceiptItemBase => {
  return {
    id: +backData.id,
    name: backData.name,
    weight: +backData.weight,
    amount: +backData.amount,
    cost: +backData.cost,
    is_confirm: backData.is_confirm == '1',
  };
};

export const mapFinanceReceiptItemToFront = (
  backData: IHikingFinanceReceiptItemDTO,
): IHikingFinanceReceiptItem => {
  return {
    ...mapFinanceReceiptItemBaseToFront(backData),

    product: backData.id_product
      ? {
          id: +backData.product_id,
          name: backData.product_name,
          carbs: +backData.product_carbohydrates,
          protein: +backData.product_protein,
          fat: +backData.product_fat,
          energy: +backData.product_energy,
        }
      : null,

    unit: backData.id_unit
      ? {
          id: +backData.unit_id,
          name: backData.unit_name,
          short_name: backData.unit_short_name,
        }
      : null,

    created_at: new Date(backData.created_at),
    updated_at: backData.updated_at ? new Date(backData.updated_at) : null,

    author: {
      id: +backData.author_id,
      name: backData.author_name,
      surname: backData.author_surname,
      photo: backData.author_photo,
    },
  };
};

export const mapFinanceReceiptItemToBackAddOrUpdate = (
  data: IHikingFinanceReceiptItem,
  id_receipt: number,
  id_hiking: number,
): IHikingFinanceReceiptItemAddOrUpdateDTO => {
  return {
    id: data.id > 0 ? data.id : undefined,
    id_hiking,
    id_receipt,
    id_product: data.product?.id ?? null,
    id_unit: data.unit?.id ?? null,
    weight: data.weight,
    amount: data.amount,
    cost: data.cost,
    name: data.name,
  };
};

export const getEmptyFinanceReceiptItem = (
  data: Partial<IHikingFinanceReceiptItem> = {},
): IHikingFinanceReceiptItem => {
  return {
    id: 0,
    name: '',
    weight: 0,
    amount: 0,
    cost: 0,
    is_confirm: false,

    product: null,

    unit: null,

    created_at: new Date(),
    updated_at: null,

    author: {
      id: 0,
      name: '',
      surname: '',
      photo: '',
    },
    ...data,
  };
};
